function UIMainPaySignEntryDialog:UpdateBuyButtonStatus()
    ----已购买
    ---@type PlayerComponent
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    -- local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
    local buyEndTime  = playerComp:GetPlayerDojo().paidCheckin.buyTime
    local leftTime = buyEndTime - os.time()
    CfUtils.SetActive(self.BtnCost.transform:Find("ImgBgLock"), false)
    CfUtils.SetActive(self.BtnCost.transform:Find("UIFX_InvestPopup_Button"), true)
    if leftTime <= 0 or checkNumber(self.data.hasBuy) == 1 then
        ---活动已结束
        CfUtils.SetActive(self.BtnCost.transform:Find("ImgBgLock"), true)
        if leftTime <= 0 then
            CfUtils.SetUISwitchText(self.BtnCost.transform:Find("ImgBgLock/TxtLock"), leftTime <= 0 and 2 or 1)
        elseif checkNumber(self.data.hasBuy) == 1 then
            CfUtils.SetUISwitchText(self.BtnCost.transform:Find("ImgBgLock/TxtLock"), 1)
        else
            CfUtils.SetUISwitchText(self.BtnCost.transform:Find("ImgBgLock/TxtLock"), 1)
        end
        CfUtils.SetActive(self.BtnCost.transform:Find("UIFX_InvestPopup_Button"), false)
    end

    if self.data and self.data.product then
        local isMoney = true
        local prices = self.data.product.prices or {}
        local count = table.count(prices)
        if count > 0 then
            isMoney = false
        end
        CfUtils.SetActive(self.TxtPriceCoin, not isMoney)
        CfUtils.SetActive(self.TxtPriceCash, isMoney)
        if isMoney then
            local payData = CfUtils.GetPayData(checkNumber(self.data.product.price), self.data.product.channelProductId)
            if payData then
                CfUtils.FillText(self.TxtPriceCash, string.format("<size=48>%s</size><size=70>%s</size>", payData.currencySymbol, payData.price))
            end
        else
            for goodsId, v in pairs(self.data.product.prices) do
                local goodPath = GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId)
                CfUtils.FillImage(self.TxtPriceCoin.transform:Find("ImgIcon"), goodPath)
                CfUtils.FillText(self.TxtPriceCoin, v.current)
                CfUtils.SetActive(self.TxtPriceCoin.transform:Find("ImgIcon"), true)
            end
        end
    end
end

--填充签到layout列表
function UIMainPaySignEntryDialog:FillSignLayout()
    local signConf = self.data.rewards
    local group = self.SingleSignListView.transform:GetComponent(typeof(HorizontalLayoutGroup))
    local normalCount = #signConf
    if group then
        group.spacing = checkNumber(normalCount)
    end

    local count = 1
    for index, signData in ipairs(signConf) do
        if index <= #signConf then
            local go = self:GetCellByIndex(count)
            self:FillItemBase(go, signData, self.data.hasBuy)
            count = count + 1
        end
    end
    if #signConf >= 14 then
        self:MoveLayoutToItem(normalCount)
    end
end

function UIMainPaySignEntryDialog:GetCellByIndex(index)
    local go = self.SingleSignListView.transform:Find("Cell" .. index)
    if not go then
        go = CfUtils.InstantiateGo(self.Cell, self.SingleSignListView)
        go.name = "Cell" .. index
    end
    return go
end

function UIMainPaySignEntryDialog:FillItemBase(go, data, hasBuy)
    hasBuy = checkNumber(hasBuy)
    if not go or not data then
        return
    end
    KTool.SetActive(go, true)

    ---@type UIActivityPaySignCellNode
    local scr = CfUtils.GetLuaScr(go, UIActivityMainSingleSignCellNode)
    if self._isTomorrow == true then
        self._isTomorrow = false
    end
    if self._isTomorrow == nil and checkInt(data.status) == Constants.GetStatus.Not and checkNumber(self.data.hasBuy) == 1 then
        self._isTomorrow = true
    end
    if scr then
        data.accumulativeLoginNum = checkNumber(data.day)
        scr:FreshBaseUI(data, self._isTomorrow,  hasBuy)
    end
    scr:SetBtnCallBack(function()
        if checkInt(data.status) == Constants.GetStatus.Can then
            self:DrawRequest(data.rewardId)
        elseif checkInt(data.status) == Constants.GetStatus.Not then
            GameUtils.Toast(localize("该日签到还未达成"))
        elseif checkInt(data.status) == Constants.GetStatus.Has then
            GameUtils.Toast(localize("该日已经签过"))
        end
    end)
end

function UIMainPaySignEntryDialog:MoveLayoutToItem(spacing)
    local posY = self.SingleSignListView.transform.anchoredPosition.y
    local leftPosX = CfUtils.GetNodeRect(self.SingleSignListView).width - CfUtils.GetNodeRect(self.LayoutCrad).width
    local cellWidth = self.Cell.transform.rect.width
    local curSignId = self:FindCurrentSignId()
    local posX = leftPosX - (curSignId - 1) * cellWidth - (curSignId - 1) * spacing
    self.SingleSignListView.transform.anchoredPosition = Vector2(posX, posY)
end

