function UIMainPaySignEntryDialog:DrawRequest(rewardsId)
    GameUtils.Request("OverseaPaidCheckin/receiveRewards",
            {rewardId = checkInt(rewardsId) },
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    local data = response.data
                    GoodsUtils.DrawRewards(checkTable(data.rewards), true)
                    UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = data.rewards }
                            }
                    )
                    self:SetSignStatusById(rewardsId)
                    self:RefreshContent()
                end
            end
    )
end

function UIMainPaySignEntryDialog:FindCurrentSignId()
    local currentId = nil
    local singleSignConf = self.data.rewards
    for index = 1, #singleSignConf do
        local itemSignData = singleSignConf[index]
        if checkInt(itemSignData.status) == Constants.GetStatus.Not then
            currentId = index == 1 and 1 or index - 1
            break
        end
    end
    if not currentId then
        currentId = #singleSignConf
    end
    return currentId
end

function UIMainPaySignEntryDialog:HasSign()
    -- ---@type PlayerComponent
    -- local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    -- local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
    -- local endTime = checkNumber(self.activityDojo.endTime)

    -- local leftTime = endTime - curDate
    local singleSignConf = self.data.rewards
    local hasSign = -1
    for index = 1, #singleSignConf do
        local itemSignData = singleSignConf[index]
        if checkInt(itemSignData.status) == Constants.GetStatus.Can then
            hasSign = 0
            break
        end
    end
    return hasSign
end

function UIMainPaySignEntryDialog:SetSignStatusById(id)
    for index = 1, #self.data.rewards do
        if self.data.rewards[index].rewardId == id then
            self.data.rewards[index].status = Constants.GetStatus.Has
            break
        end
    end
end

function UIMainPaySignEntryDialog:HandleStateTimeDown()
    self:ClearTimeDown()
    ---@type PlayerDojo
    local playerDojo =  GameUtils.GetPlayerDojo()
    print("===============>>")
    print(table.dump(playerDojo.paidCheckin))
    local hasBuy = checkInt(playerDojo.paidCheckin.hasBuy) 
    local endTime = playerDojo.paidCheckin.buyTime
    CfUtils.FillText(self.TxtActivity , localize("可购买时间:"))
    if hasBuy == 1 then
        CfUtils.FillText(self.TxtActivity , localize("可签到时间:"))
        endTime = playerDojo.paidCheckin.checkinTime    
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS2(endTime - os.time()))
     end, CountDownTime, false, true)
end

function UIMainPaySignEntryDialog:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function UIMainPaySignEntryDialog:OnFinalize()
    if self.__EventSdkEvent then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
        self.__EventSdkEvent = nil
    end
    self:ClearTimeDown()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function UIMainPaySignEntryDialog:OnPayAction()
    if not self.data then
        return
    end
   ---购买的逻辑
   ---@type PlayerComponent
--    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = GameUtils.GetPlayerDojo()
    local buyTime = playerDojo.paidCheckin.buyTime
    local leftTime = buyTime - os.time()
    -- local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
    -- local endTime = checkNumber(self.activityDojo.endTime)
    -- local leftTime = endTime - curDate
    --CfUtils.SetActive(self.BtnCost.transform:Find("ImgBgLock"), false)
    -- if leftTime <= 0 then
    --     GameUtils.Toast(localize('活动已经结束'))
    --     return
    -- end
    if checkNumber(self.data.hasBuy) == 1 then
        GameUtils.Toast(localize('已购买'))
        return
    end
    local isMoney = true
    local prices = self.data.product.prices or {}
    local count = table.count(prices)
    if count > 0 then
        isMoney = false
    end
    if isMoney then
        local SDKService = import('Game.Entry.SDKService')
        ---sdk购买
        local product = self.data.product
        SDKService:GetInstance():PayMoney({
            productId = product.productId,
            channelProductId = product.channelProductId,
            productDesc = localize('付费签到'),
            payAmount = checkNumber(product.price),
            data = product
        })
    else
        local product = self.data.product
        local goodsId = checkNumber(table.takeFirst(table.keys(product.prices)))
        local dojo = self.data.product.prices[tostring(goodsId)]
        local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
        ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
            currency = goodsId,
            current = dojo.current,
        },function()
            GameUtils.Request("OverseaMall/residentPaidCheckinBuy",{productId = product.productId, num = dojo.current ,currency = goodsId},function(request,response)
                if checkNumber(response.errCode) == 0 then
                    local data = response.data
                    GoodsUtils.DrawRewards({ { goodsId = goodsId, num = - checkNumber(dojo.current), productId = checkNumber(product.productId) } }, true)
                    if #data.rewards > 0 then
                        GoodsUtils.DrawRewards(data.rewards)
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = data.rewards, cb = function()
                                        Events.Broadcast(Constants.EventNames.OverseaMallRenovateBuySuccess)
                                    end }
                                }
                        )
                    end
                    ---更新界面
                    self:UpdateAllInfo()
                end
            end)
        end)
    end
end

function UIMainPaySignEntryDialog:UpdateAllInfo()
    GameUtils.Request("OverseaPaidCheckin/home", {}, function(request, response)
        if checkInt(response.errCode) == 0 then
            self.data = checkTable(response.data)
            CfUtils.SetActive(self.LayoutCrad, true)
            GameUtils.GetPlayerDojo():UpdatePaidCheckin(self.data)
            self:HandleStateTimeDown()
            self:RefreshContent()
        end
    end)
end

function UIMainPaySignEntryDialog:OnEventSdkEvent(parameters)
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
       ---购买成功了
       self:UpdateAllInfo()
    end
end

return UIMainPaySignEntryDialog
